    name: "Ergitme Filtresi Sıyırıcı Bıçakları",
    fullName:
      "Sürekli Erime Filtreleri için Üst Sınıf Kazıyıcı Bıçakları ve Filtre Plakaları",
    category: "granulator_blades",
    sector: "recycling",
